def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Check if we're at end of line or have processed a comma
        if i == len(line):
            # Add the last field (could be empty if line ends with comma)
            fields.append('')
            break

        # Start of a new field
        if line[i] == '"':
            # Quoted field
            i += 1
            field = ''
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote or the closing quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field += '"'
                        i += 2
                    else:
                        # Closing quote found
                        i += 1
                        # Check what follows: must be comma or end of line
                        if i == len(line):
                            fields.append(field)
                            return fields
                        elif line[i] == ',':
                            fields.append(field)
                            i += 1
                            # If we're at end after comma, add empty field
                            if i == len(line):
                                fields.append('')
                                return fields
                            # Continue to next field
                            break
                        else:
                            # Invalid: closing quote not followed by comma or EOL
                            return None
                else:
                    field += line[i]
                    i += 1

            if i > len(line):
                # Unterminated quoted field
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain quotes
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            if i < len(line) and line[i] == ',':
                i += 1
                # If we're at end after comma, add empty field
                if i == len(line):
                    fields.append('')
                    return fields

    return fields

